conditions.leftValue:
={{ (() => {
  const normalize = (value) => String(value ?? '').trim().toLowerCase();
  const sameJourneyKey = $('Buscar Jornadas Recuperáveis').all()
    .map((item) => item.json)
    .filter((journey) =>
      normalize(journey.buyer_email) === normalize($json.buyer_email) &&
      Number(journey.product_id ?? 0) === Number($json.product_id ?? 0) &&
      normalize(journey.offer_code) === normalize($json.offer_code)
    );
  const newestId = Math.max(...sameJourneyKey.map((journey) => Number(journey.id ?? 0)));
  if (sameJourneyKey.length > 1 && Number($json.id ?? 0) !== newestId) return false;
  const due = $json.next_step_at === null || $json.next_step_at === undefined || new Date($json.next_step_at).getTime() <= Date.now();
  if (!due) return false;
  const first = Number($json.last_step_sent || 0) === 0;
  const waiting = String($json.current_status || $json.recovery_flow || '').trim().toUpperCase() === 'WAITING_PAYMENT';
  if (!first || !waiting) return true;
  const raw = $json.last_event_created_at ?? $json.created_at;
  const numeric = Number(raw);
  const eventTime = Number.isFinite(numeric) && numeric > 0 ? (numeric < 1000000000000 ? numeric * 1000 : numeric) : Date.parse(String(raw || ''));
  return !Number.isFinite(eventTime) || Date.now() >= eventTime + 10 * 60 * 1000;
})() }}

parameters.message:
={{ (() => {
    const p = $('Preparar E-mail - Etapa 1').item.json || {};
    const token = String($('Reservar Envio - Etapa 1').item.json.tracking_token || '').trim();
    const checkout = String($('Qual etapa Enviar?').item.json.checkout_url || 'https://example.invalid');
    const url = token ? 'https://example.invalid' + encodeURIComponent(token) : checkout;
    const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    const paragraphs = String(p.email_body || '').split(/\n\n+/).map(x => '<p style="margin:0 0 16px">' + esc(x).replace(/\n/g,'<br>') + '</p>').join('');
    const pre = esc(p.email_preheader || '');
    const button = esc(p.email_button || 'ACESSAR MEU PEDIDO');
    const footer = esc(p.email_footer || '');
    return '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent">' + pre + '</div>' +
      '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;color:#202124;font-size:16px;line-height:1.65">' +
      paragraphs +
      '<div style="margin:24px 0;text-align:center"><a href="' + esc(url) + '" style="display:inline-block;background:#111827;color:#ffffff;text-decoration:none;font-weight:700;padding:14px 22px;border-radius:8px">' + button + '</a></div>' +
      '<p style="margin:0 0 16px;font-size:13px;color:#5f6368">Se o botão não abrir, use este link:<br><a href="' + esc(url) + '">' + esc(url) + '</a></p>' +
      '<p style="margin-top:24px">' + footer + '</p></div>';
  })() }}

